-- RSS AI Project Manager security foundation
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, password_hash TEXT, email_verified BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS workspaces (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, owner_user_id UUID REFERENCES users(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','deleted')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS workspace_members (workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('owner','admin','manager','developer','member','viewer')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (workspace_id,user_id));
CREATE TABLE IF NOT EXISTS service_entitlements (workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, service_key TEXT NOT NULL CHECK (service_key IN ('project_manager','rss_core','rss_kit','ray')), enabled BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (workspace_id,service_key));
CREATE TABLE IF NOT EXISTS sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), revoked_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS audit_log (id BIGSERIAL PRIMARY KEY, workspace_id UUID REFERENCES workspaces(id) ON DELETE SET NULL, user_id UUID REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, resource_type TEXT, resource_id TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE projects ADD COLUMN IF NOT EXISTS workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE;
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE;
ALTER TABLE project_memory ADD COLUMN IF NOT EXISTS workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE;
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE;
ALTER TABLE activity_log ADD COLUMN IF NOT EXISTS workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE;
INSERT INTO workspaces (id,name,status) VALUES ('00000000-0000-0000-0000-000000000001','RSS Workspace','active') ON CONFLICT (id) DO NOTHING;
UPDATE projects SET workspace_id='00000000-0000-0000-0000-000000000001' WHERE workspace_id IS NULL;
UPDATE conversations SET workspace_id='00000000-0000-0000-0000-000000000001' WHERE workspace_id IS NULL;
UPDATE project_memory pm SET workspace_id=p.workspace_id FROM projects p WHERE pm.project_id=p.id AND pm.workspace_id IS NULL;
UPDATE tasks t SET workspace_id=p.workspace_id FROM projects p WHERE t.project_id=p.id AND t.workspace_id IS NULL;
UPDATE activity_log a SET workspace_id=p.workspace_id FROM projects p WHERE a.project_id=p.id AND a.workspace_id IS NULL;
INSERT INTO service_entitlements(workspace_id,service_key,enabled) SELECT '00000000-0000-0000-0000-000000000001',service_key,TRUE FROM unnest(ARRAY['project_manager','rss_core','rss_kit','ray']) AS service_key ON CONFLICT (workspace_id,service_key) DO NOTHING;
CREATE INDEX IF NOT EXISTS idx_projects_workspace ON projects(workspace_id);
CREATE INDEX IF NOT EXISTS idx_conversations_workspace ON conversations(workspace_id);
CREATE INDEX IF NOT EXISTS idx_memory_workspace ON project_memory(workspace_id);
CREATE INDEX IF NOT EXISTS idx_tasks_workspace ON tasks(workspace_id);
CREATE INDEX IF NOT EXISTS idx_activity_workspace ON activity_log(workspace_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_members_user ON workspace_members(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_expiry ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_audit_workspace ON audit_log(workspace_id,created_at DESC);